// Edge function: heartbeat
// Phone POSTs a periodic heartbeat while the bridge foreground service is
// running. The body contains:
//   {
//     "device_id": "<uuid>",                  // stable per-install UUID generated by the phone
//     "name": "Pixel 8 (Work)",                // user-set friendly name (falls back to Build.MODEL)
//     "session_id": "<uuid>",                  // generated per RealtimeService.onCreate()
//     "pid": <int>,                             // android.os.Process.myPid() at start
//     "device_model": "Pixel 8",                // Build.MODEL
//     "manufacturer": "Google",                 // Build.MANUFACTURER
//     "product": "akita",                       // Build.PRODUCT
//     "device_codename": "akita",               // Build.DEVICE
//     "android_version": "14",                  // Build.VERSION.RELEASE
//     "sdk_int": <int>,                          // Build.VERSION.SDK_INT
//     "privilege_level": "shizuku",              // "root" | "shizuku-root" | "shizuku-adb" | "app" — computed by the phone
//     "shizuku_uid": <int>,                      // 0=root, 2000=adb, -1=not available — distinguishes root vs adb Shizuku
//     "currently_executing_id": <bigint|null>   // command id mid-dispatch, or null if idle
//   }
//
// This function:
//   1. Upserts into the devices table (keyed by device_id) — refreshing
//      last_alive_at = now(), session_id, name, model, manufacturer, etc,
//      status='online', and currently_executing_id.
//   2. If currently_executing_id is non-null, also bumps
//      commands.last_heartbeat_at = now() for that command.
//
// The get-result edge function uses the devices.last_alive_at column to detect
// dead executors: if a command is status='processing' but the heartbeat is
// older than 30s (or the session_id doesn't match the one stored on the
// command), it auto-fails the row.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "authorization, content-type, apikey, x-bridge-token",
};

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: CORS });
  }
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "POST only" }), {
      status: 405,
      headers: { ...CORS, "Content-Type": "application/json" },
    });
  }
  try {
    const body = await req.json();
    const deviceId = body?.device_id;
    if (!deviceId || typeof deviceId !== "string") {
      return new Response(JSON.stringify({ error: "device_id (string) required" }), {
        status: 400,
        headers: { ...CORS, "Content-Type": "application/json" },
      });
    }
    const sessionId = body?.session_id;
    if (!sessionId || typeof sessionId !== "string") {
      return new Response(JSON.stringify({ error: "session_id (string) required" }), {
        status: 400,
        headers: { ...CORS, "Content-Type": "application/json" },
      });
    }
    const name = body?.name !== undefined && body?.name !== null ? String(body.name) : null;
    const model = body?.device_model !== undefined && body?.device_model !== null ? String(body.device_model) : null;
    const manufacturer = body?.manufacturer !== undefined && body?.manufacturer !== null ? String(body.manufacturer) : null;
    const product = body?.product !== undefined && body?.product !== null ? String(body.product) : null;
    const deviceCodename = body?.device_codename !== undefined && body?.device_codename !== null ? String(body.device_codename) : null;
    const androidVersion = body?.android_version !== undefined && body?.android_version !== null ? String(body.android_version) : null;
    const sdkInt = body?.sdk_int !== undefined && body?.sdk_int !== null ? Number(body.sdk_int) : null;
    const privilegeLevel = body?.privilege_level !== undefined && body?.privilege_level !== null ? String(body.privilege_level) : null;
    const shizukuUid = body?.shizuku_uid !== undefined && body?.shizuku_uid !== null ? Number(body.shizuku_uid) : null;
    const pid = body?.pid !== undefined && body?.pid !== null ? Number(body.pid) : null;
    const currentlyExecutingId = body?.currently_executing_id !== undefined && body?.currently_executing_id !== null ? Number(body.currently_executing_id) : null;

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SECRET_KEY") ?? Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const nowIso = new Date().toISOString();

    // 1. Upsert devices (keyed by device_id).
    //    On conflict over (device_id), update everything — a restart of the
    //    bridge foreground service for THIS device gets a fresh session_id,
    //    started_at, last_alive_at, etc.
    const deviceRow: Record<string, unknown> = {
      device_id: deviceId,
      session_id: sessionId,
      status: "online",
      last_alive_at: nowIso,
      last_seen_at: nowIso,
    };
    if (name !== null) deviceRow.name = name;
    if (model !== null) deviceRow.model = model;
    if (manufacturer !== null) deviceRow.manufacturer = manufacturer;
    if (product !== null) deviceRow.product = product;
    if (deviceCodename !== null) deviceRow.device_codename = deviceCodename;
    if (androidVersion !== null) deviceRow.android_version = androidVersion;
    if (sdkInt !== null && Number.isFinite(sdkInt)) deviceRow.sdk_int = sdkInt;
    if (privilegeLevel !== null) deviceRow.privilege_level = privilegeLevel;
    if (shizukuUid !== null && Number.isFinite(shizukuUid)) deviceRow.shizuku_uid = shizukuUid;
    if (pid !== null) deviceRow.pid = pid;
    if (currentlyExecutingId !== null) deviceRow.currently_executing_id = currentlyExecutingId;
    else deviceRow.currently_executing_id = null;
    // started_at is only set on a fresh insert (handled by the table default)
    // — but if this is an existing row, we don't want to overwrite it. Use
    // the upsert's onConflict="device_id" with updateColumns to only touch
    // the fields we want to refresh. Simpler: do an explicit pre-check.

    // Check if this device already exists. If not, this is a fresh start —
    // set started_at = now(). If yes, leave started_at alone.
    const { data: existing } = await supabase
      .from("devices")
      .select("device_id, started_at")
      .eq("device_id", deviceId)
      .maybeSingle();
    if (!existing) {
      deviceRow.started_at = nowIso;
    }

    const { error: upsertErr } = await supabase
      .from("devices")
      .upsert(deviceRow, { onConflict: "device_id" });
    if (upsertErr) {
      return new Response(JSON.stringify({ error: "device upsert failed: " + upsertErr.message }), {
        status: 500,
        headers: { ...CORS, "Content-Type": "application/json" },
      });
    }

    // 2. If a command is mid-execution, bump its last_heartbeat_at too — so
    //    the AI agent can compute liveness for an individual command without
    //    needing to JOIN the devices table.
    if (currentlyExecutingId !== null && Number.isFinite(currentlyExecutingId)) {
      const { error: hbErr } = await supabase
        .from("commands")
        .update({ last_heartbeat_at: nowIso })
        .eq("id", currentlyExecutingId)
        .eq("status", "processing");  // don't bump rows that already completed
      if (hbErr) {
        // Non-fatal: the device heartbeat already proves liveness.
        console.warn("failed to bump command heartbeat", hbErr.message);
      }
    }

    return new Response(JSON.stringify({
      ok: true,
      server_time: nowIso,
      device_id: deviceId,
      session_id: sessionId,
      name: name,
      currently_executing_id: currentlyExecutingId,
    }), { status: 200, headers: { ...CORS, "Content-Type": "application/json" } });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), {
      status: 400,
      headers: { ...CORS, "Content-Type": "application/json" },
    });
  }
});
